mapper.insert:
INSERT INTO PDS_FILE (
file_id
, file_type
, file_name
, sort_number
, file_size
, width
, height
, duration
, content_type
, del_yn
, pds_id
, created_at
, changed_at
) VALUES (
#{fileId}
, #{fileType}
, #{fileName}
, #{sortNumber}
, #{fileSize}
, #{width}
, #{height}
, #{duration}
, #{contentType}
, #{delYn}
, #{pdsId}
, #{createdAt}
, #{changedAt}
)

mapper.update:
UPDATE PDS_FILE
SET pds_id      = #{pdsId}
, sort_number = #{sortNumber}
, del_yn      = 'N'
, changed_at  = CURRENT_TIMESTAMP
WHERE file_id = #{fileId}

UPDATE PDS_FILE
SET file_name  = #{fileName}
, changed_at = CURRENT_TIMESTAMP
WHERE file_id    = #{fileId}

mapper.select:
SELECT a.*
FROM PDS_FILE a
WHERE a.file_id = #{value}

SELECT EXISTS (
SELECT 1
FROM PDS_FILE
WHERE file_id = #{value}
)

SELECT a.file_id
FROM PDS_FILE a
WHERE a.pds_id = #{value}
